UPDATE transport_command
SET status = 'PUBLISHED', published_at = #{publishedAt}, updated_at = #{updatedAt}
WHERE command_id = #{commandId} AND status = 'CREATED'

UPDATE transport_command
SET status = 'ACKNOWLEDGED', acknowledged_at = #{acknowledgedAt}, updated_at = #{updatedAt}
WHERE command_id = #{commandId} AND status = 'PUBLISHED'

UPDATE transport_command
SET status = 'SUCCEEDED', completed_at = #{completedAt}, updated_at = #{updatedAt}
WHERE command_id = #{commandId} AND status IN ('PUBLISHED', 'ACKNOWLEDGED')

UPDATE transport_command
SET status = 'PUBLISH_FAILED', failure_reason = #{failureReason}, updated_at = #{updatedAt}
WHERE command_id = #{commandId} AND status = 'CREATED'

UPDATE transport_command
SET status = 'TIMEOUT', updated_at = #{updatedAt}
WHERE command_id = #{commandId} AND status IN ('PUBLISHED', 'ACKNOWLEDGED')

UPDATE transport_command
SET status = #{toStatus}, updated_at = #{updatedAt}
WHERE command_id = #{commandId} AND status = #{fromStatus}
